import re,os,sys
from html.parser import HTMLParser
VOID={"area","base","br","col","embed","hr","img","input","link","meta","source","track","wbr"}
class P(HTMLParser):
    def __init__(s): super().__init__(convert_charrefs=True); s.st=[]; s.er=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.st.append(t)
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.st: s.er.append("stray </%s>"%t)
        elif s.st[-1]!=t: s.er.append("</%s> closes <%s>"%(t,s.st[-1]))
        else: s.st.pop()
bad=0
for f in ["my_website/index.html","my_website/blog.html","my_website/publications.html"]:
    src=open(f,encoding="utf-8").read()
    p=P(); p.feed(src); errs=p.er+["unclosed <%s>"%t for t in p.st]
    if "<script" in src.lower(): errs.append("script tag")
    for m in re.finditer(r'(?:href|src)="([^"]*)"',src):
        u=m.group(1)
        if u=="#": errs.append("dead anchor"); continue
        if u.startswith(("mailto:","https://","http://")): continue
        if not os.path.isfile(os.path.join("my_website",u.split("#")[0])): errs.append("missing "+u)
    print(f, "OK" if not errs else "FAIL: "+"; ".join(errs)); bad+=bool(errs)
print("RESULT","OK" if not bad else "FAIL"); sys.exit(1 if bad else 0)
